    map['amount'] = Variable<int>(amount);
    map['method'] = Variable<String>(method);
    map['detail'] = Variable<String>(detail);
    map['ref_type'] = Variable<String>(refType);
    map['ref_id'] = Variable<int>(refId);
    return map;
  }

